-- Seed DB: 250 students, 5 classes, 50 UNIQUE students per class
-- Students: student01..student250 / 123456
-- Lecturer: lecturer01 / 123456
-- Attendance password: Pass@123
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS attendance_records;
DROP TABLE IF EXISTS attendance_sessions;
DROP TABLE IF EXISTS schedules;
DROP TABLE IF EXISTS enrollments;
DROP TABLE IF EXISTS class_sections;
DROP TABLE IF EXISTS courses;
DROP TABLE IF EXISTS lecturers;
DROP TABLE IF EXISTS students;
DROP TABLE IF EXISTS users;
CREATE TABLE users (userID INT AUTO_INCREMENT PRIMARY KEY,userName VARCHAR(50) NOT NULL UNIQUE,passwordHash VARCHAR(255) NOT NULL,fullName VARCHAR(100) NOT NULL,email VARCHAR(100) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',role VARCHAR(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE students (studentID INT AUTO_INCREMENT PRIMARY KEY,userID INT NOT NULL UNIQUE,studentCode VARCHAR(20) NOT NULL UNIQUE,fullName VARCHAR(100) NOT NULL,dateOfBirth DATE NULL,gender VARCHAR(20) NULL,major VARCHAR(100) NULL,FOREIGN KEY (userID) REFERENCES users(userID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE lecturers (lecturerID INT AUTO_INCREMENT PRIMARY KEY,userID INT NOT NULL UNIQUE,lecturerCode VARCHAR(20) NOT NULL UNIQUE,fullName VARCHAR(100) NOT NULL,department VARCHAR(100) NULL,FOREIGN KEY (userID) REFERENCES users(userID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE courses (courseID INT AUTO_INCREMENT PRIMARY KEY,courseCode VARCHAR(20) NOT NULL UNIQUE,courseName VARCHAR(150) NOT NULL,credits INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE class_sections (classID INT AUTO_INCREMENT PRIMARY KEY,courseID INT NOT NULL,lecturerID INT NOT NULL,classCode VARCHAR(30) NOT NULL UNIQUE,semester VARCHAR(20) NOT NULL,academicYear VARCHAR(20) NOT NULL,FOREIGN KEY (courseID) REFERENCES courses(courseID),FOREIGN KEY (lecturerID) REFERENCES lecturers(lecturerID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE enrollments (enrollmentID INT AUTO_INCREMENT PRIMARY KEY,studentID INT NOT NULL,classID INT NOT NULL,enrollmentDate DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',FOREIGN KEY (studentID) REFERENCES students(studentID),FOREIGN KEY (classID) REFERENCES class_sections(classID),UNIQUE KEY uq_enroll (studentID,classID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE schedules (scheduleID INT AUTO_INCREMENT PRIMARY KEY,classID INT NOT NULL,dayOfWeek VARCHAR(20) NOT NULL,startTime TIME NOT NULL,endTime TIME NOT NULL,room VARCHAR(50) NOT NULL,FOREIGN KEY (classID) REFERENCES class_sections(classID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE attendance_sessions (sessionID INT AUTO_INCREMENT PRIMARY KEY,classID INT NOT NULL,sessionDate DATE NOT NULL,startTime TIME NOT NULL,endTime TIME NOT NULL,attendanceMethod VARCHAR(20) NOT NULL,attendancePasswordHash VARCHAR(255) NULL,status VARCHAR(20) NOT NULL,FOREIGN KEY (classID) REFERENCES class_sections(classID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE attendance_records (attendanceID INT AUTO_INCREMENT PRIMARY KEY,sessionID INT NOT NULL,studentID INT NOT NULL,status VARCHAR(20) NOT NULL,checkInTime DATETIME NULL,method VARCHAR(20) NULL,remark VARCHAR(255) NULL,FOREIGN KEY (sessionID) REFERENCES attendance_sessions(sessionID),FOREIGN KEY (studentID) REFERENCES students(studentID),UNIQUE KEY uq_attendance (sessionID,studentID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- Class 1: studentID 1..50
-- Class 2: studentID 51..100
-- Class 3: studentID 101..150
-- Class 4: studentID 151..200
-- Class 5: studentID 201..250
SET FOREIGN_KEY_CHECKS=1;
SELECT COUNT(*) AS students FROM students;
SELECT classID,COUNT(*) AS student_count FROM enrollments GROUP BY classID ORDER BY classID;